class GPT20B(GPT):

    # is_add_stats = False
            
    def __init__(self, config):
        # super(GPT,self).__init__(config)
        super(GPT,self).__init__()

    # def __init__(self, config):
    #     super().__init__()
        assert config.vocab_size is not None
        assert config.block_size is not None
        self.config = config
        ne = config.n_embd
        nl = config.n_layer
        ng = config.n_head

        self.transformer = nn.ModuleDict(dict(
            wte = nn.Embedding(config.vocab_size, config.n_embd),
            wpe = nn.Embedding(config.block_size, config.n_embd),
            drop = nn.Dropout(config.dropout),
            # output = nn.Linear(ne*nl,ng*ne,bias=False),
            # gates = nn.Linear(ne*nl,ng,bias=True),
            h = nn.ModuleList([Block20B(config) for _ in range(config.n_layer)]),
            h2 = nn.ModuleList([Block20B(config) for _ in range(config.n_layer)]),
            ln_f = LayerNorm(config.n_embd, bias=config.bias),
        ))
        self.lm_head = nn.Linear(config.n_embd, config.vocab_size, bias=False)
        # with weight tying when using torch.compile() some warnings get generated:
        # "UserWarning: functional_call was passed multiple values for tied weights.
        # This behavior is deprecated and will be an error in future versions"
        # not 100% sure what this is, so far seems to be harmless. TODO investigate
        self.transformer.wte.weight = self.lm_head.weight # https://paperswithcode.com/method/weight-tying

        # init all weights
        self.apply(self._init_weights)
        # apply special scaled init to the residual projections, per GPT-2 paper
        for pn, p in self.named_parameters():
            if pn.endswith('c_proj.weight'):
                torch.nn.init.normal_(p, mean=0.0, std=0.02/math.sqrt(2 * config.n_layer))

        # report number of parameters
        print("number of parameters: %.2fM" % (self.get_num_params()/1e6,))

    def _forward_tfm(self,tfm_h,x):
        x0 = x
        for i,block in enumerate(tfm_h):
            x = block(x0,x)
            # states[:,:,i] = x
        x = x
        x = self.transformer.ln_f(x)
        return x
    def forward(self, idx, targets=None):


        md = self.transformer ### model dict


        # forward the GPT model itself

        config = self.config
        nl = config.n_layer
        ne = config.n_embd
        nh = config.n_head


        device = idx.device
        b, t = idx.size()
        assert t <= self.config.block_size, f"Cannot forward sequence of length {t}, block size is only {self.config.block_size}"
        pos = torch.arange(0, t, dtype=torch.long, device=device) # shape (t)

        # forward the GPT model itself
        tok_emb = self.transformer.wte(idx) # token embeddings of shape (b, t, n_embd)
        pos_emb = self.transformer.wpe(pos) # position embeddings of shape (t, n_embd)
        # x = self.transformer.drop(tok_emb + pos_emb)
        x = (tok_emb + pos_emb)

        x1 = self._forward_tfm(self.transformer.h, x)
        x2 = self._forward_tfm(self.transformer.h2, x)
        # states = torch.zeros((b,t,nl,ne),device=device)


        # x = torch.einsum('btk,btke->bte',gates,md.output(xx).reshape((b,t,-1,ne)))



        if targets is not None:
            # if we are given some desired targets also calculate the loss
            # logits = self.lm_head(x)
            # loss = F.cross_entropy(logits.view(-1, logits.size(-1)), targets.view(-1), ignore_index=-1)

            # if self.training:
            ncat = 2
            if not self.training:
                ### eval
                logits  = self.lm_head(x1)
                logits2 = self.lm_head(x2)

                loss = F.cross_entropy(logits.view(-1, logits.size(-1)), targets.view(-1), ignore_index=-1,reduction='none')
                loss2 = F.cross_entropy(logits2.view(-1, logits2.size(-1)), targets.view(-1), ignore_index=-1,reduction='none')
                lp = (-torch.stack((loss,loss2),-1)).logsumexp(-1) + math.log(1./ncat)
                loss = -lp.mean() 
            else:
                xs = torch.stack([x1,x2],dim=0)
                engp = torch.einsum('nbte,bte->nbt', xs, self.transformer.wte(targets))

                ### bt
                idxb = torch.arange(b,device=device)[:,None]
                idxt = torch.arange(t,device=device)[None,:]
                v,idx = engp.max(dim=0)

                x1 = xs[idx,idxb,idxt,:]  ## bte
                logits  = self.lm_head(x1)
                loss = F.cross_entropy(logits.view(-1, logits.size(-1)), targets.view(-1), ignore_index=-1,reduction='none')
                loss = (loss - math.log(1./ncat)).mean() 



        else:
            # inference-time mini-optimization: only forward the lm_head on the very last position
            logits = self.lm_head(x[:, [-1], :]) # note: using list [-1] to preserve the time dim
            loss = None

        return logits, loss




class Block023(nn.Module):

    def __init__(self, config):
        super().__init__()
        self.ln_1 = LayerNorm(config.n_embd, bias=config.bias)
        # self.attn = CausalSelfAttention(config)
        self.ln_2 = LayerNorm(config.n_embd, bias=config.bias)
        # self.mlp = MLP11(config)
        self.mlp = MLP(config)
        ne = config.n_embd
        ng = config.n_head

        self.k_attn_1a = nn.Linear(ne, ne,bias=config.bias)
        self.k_attn_1c = nn.Linear(ne, ng*ne,bias=config.bias)
        self.k_attn_1d = nn.Linear(ne, ng*ne,bias=config.bias)
        self.c_proj    = nn.Linear(ne, ne,bias=config.bias)


    def forward(self, x0, x):
        ne = x0.shape[-1]
        b,t = x0.shape[:2]
        device= x0.device
        att_mask = torch.ones((t,t),device=device).bool()
        ### (tc,tp)
        att_mask      = torch.tril(att_mask, diagonal=0)
        att_mask[0,0] =True
        x0 = _lnorm(x0)

        xq1 = self.k_attn_1c(x0).reshape((b,t,-1,ne))
        # xq1 = _lnorm(xq1)
        # xq3 = (self.k_attn_1d(x0).reshape((b,t,-1,ne)))
        xq2 = (self.k_attn_1a(_lnorm(x)))
        engp = torch.einsum('bpke,bte->btpk', xq1, xq2) / ne**0.5
        engp = engp.masked_fill(att_mask[None,:t,:t,None] == 0, float('-inf'))
        att  = engp.reshape((b,t,-1)).softmax(-1).reshape(engp.shape)

        ### use v vector in ca
        # yinput = torch.einsum('btpk,bpke->bte',att,xq3)
        # yinput = self.c_proj(yinput)

        yinput = torch.einsum('btpk,bpke->bte',att,xq1)
        yinput = self.c_proj(yinput)
        x = (x + yinput)

        # xq2 = 
        x = x + self.mlp(self.ln_2(x))
        return x


