        # post_logsigma  = self.post_logsigma
        # post_invsqsigma = 1./(2*post_logsigma).exp()

        ### side length of the box
        rd = 2
        # rd = 1.
        # rd = 0.05

        xz = xz.clip(-rd/2,rd/2)
        blow = -rd/2
        bhigh = rd/2

        rnoise = self.post_logrnoise.exp()
        # 1.
        betas = torch.ones_like(xz)*self.post_logbeta.exp()
        dist_post = torch.distributions.beta.Beta(betas,betas)
        pnoise = dist_post.sample()

        ### make sure the random variable falls within the box
        low = (xz-rnoise/2.).clip(blow,)
        high = (xz+rnoise/2.).clip(bhigh)

        lpq = -(high-low).log() + dist_post.log_prob(pnoise)
