        idx1 = torch.cat([idx,torch.ones_like(idx[:,:nm]).long()*(self.vmax-1)],dim=1)
        tok_emb = self.transformer.wte(idx1) # token embeddings of shape (b, t, n_embd)
        pos_emb = self.transformer.wpe(pos) # position embeddings of shape (t, n_embd)
        x = tok_emb + pos_emb

        for block in self.transformer.h_enc:
            x = block(x,x)
        x = self.transformer.ln_f2(x)

        ### truncating the output to desired dimension
        xz = x[:,-nm:]
        xz = xz[:,:,:self.nm_a]



        ### quantised variable
        ### ns*b,m
        prior_logsigma = torch.tensor(math.log(0.5),device=x.device)
        invsqsigma = 1./(2*prior_logsigma).exp()
        ### OOD penalisation
        lpe  = -0.5*invsqsigma*(xz - xz.clip(low,high)).square().sum(-1)
        lpe  = torch.zeros_like(lpe)
        lpe2 = torch.zeros_like(lpe)
        lpz  = torch.zeros_like(lpe)

        prior_logsigma = self.prior_logsigma_2
        invsqsigma = 1./(2*prior_logsigma).exp()
        zgrid = torch.linspace(self.low,self.high,self.nsep,device=device)
        lpe =  -0.5*invsqsigma[0] * (xz - xz.clip(self.low,self.high)).square()
        
        lpe = lpe.sum(-1)

        def gridify(xz):
            xz_int= ((xz - self.low)//self.sep).long()
            return xz_int

