            comp_out = nn.Linear(nm_a,config.n_embd, bias=False),

            drop = nn.Dropout(config.dropout),
            
            # h0 = nn.ModuleList([Block140(config) for _ in range(1)]),
            h_dec = nn.ModuleList([Block235(config) for _ in range(config.n_layer//2)]),
            h_dec2 = nn.ModuleList([Block235(config) for _ in range(config.n_layer//2)]),
            # h_next = nn.ModuleList([Block235(config) for _ in range(config.n_layer//2)]),
            h_enc = nn.ModuleList([Block235(config) for _ in range(config.n_layer//2)] ),
            h_latent = nn.ModuleList([Block235(config,is_causal=False) for _ in range(config.n_layer//2)] ),
            # h_ar = nn.ModuleList([Block235(config) for _ in range(config.n_layer)] ),
            # hlast = Block231(config),
