    def forward(self, idx, targets=None):
        '''
        the first token of index is masked to vmax-2
        '''

        device = idx.device
        b, t = idx.size()
        assert t <= self.config.block_size, f"Cannot forward sequence of length {t}, block size is only {self.config.block_size}"
        low = self.low
        high = self.high
        nsep = self.nsep
        sep = self.sep

        ns = self.ns
        nm = self.nm
        nm_a = self.nm_a
        

        # self.prior_logsigma.data = math.log(3.0)*torch.ones_like(self.prior_logsigma.data )
        # self.prior_logsigma_2.data[0] = math.log(2.3)*torch.ones_like(self.prior_logsigma_2.data[0] )
        # self.prior_logsigma_2.data[1] = math.log(0.5)*torch.ones_like(self.prior_logsigma_2.data[1] )
        # i=2;self.prior_logsigma_2.data[i] = math.log(0.5)*torch.ones_like(self.prior_logsigma_2.data[i] )
        # i=3;self.prior_logsigma_2.data[i] = math.log(0.5)*torch.ones_like(self.prior_logsigma_2.data[i] )

        if self.reset and not self.training:

            print([
                self.prior_logsigma_2.exp(),
             ])
            self.reset = False
        if self.training:
            self.reset = True

        x = idx

        idx = idx.repeat((ns,1,1)).reshape((ns*b,t))
        targets = targets.repeat((ns,1,1)).reshape((ns*b,t))
        idx,idx2 = torch.split(idx,t//2,1)
        targets, targets2 = torch.split(targets,t//2,1) 
        t2 = t//2



        prefix   = self.get_init_prefix(idx)
        ### for sequence autoencoding
        idxc = torch.cat([torch.ones_like(idx[:,:1]).long()*self.token_ae1,idx], dim=1)
        prefix   = self.encode_into_suffix(self.transformer.h_enc, prefix, prefix,idxc)
        prefix   = self.transformer.comp_out(self.transformer.comp_in(prefix))


        _disabled = self._disabled
        # _disabled = 1;  
        if _disabled:
            print('[DEBUG]Disabling the latent!!!!!!!!------------')
            prefix = prefix.flip((0,))

        logits, lpy = self.decode_with_prefix(self.transformer.h_dec, prefix, idx,targets)
        reverted = 0
        reverted =  0
        if reverted:
            print('reverted')
            logits, lpy = self.decode_with_prefix(self.transformer.h_dec, prefix, idx2,targets2)

        prefix1 = prefix


        ### for sequence completion
        prefix   = self.get_init_prefix(idx)
        ### prefixing auto-completion token 
        idxc = torch.cat([torch.ones_like(idx[:,:1]).long()*self.token_comp1,idx], dim=1)
        prefix   = self.encode_into_suffix(self.transformer.h_enc, prefix, prefix,idxc)
        prefix   = self.transformer.comp_out(self.transformer.comp_in(prefix))

        _disabled = self._disabled
        # _disabled = 1;  
        if _disabled:
            print('[DEBUG]Disabling the latent!!!!!!!!------------')
            prefix = prefix.flip((0,))

        logits2, lpy2 = self.decode_with_prefix(self.transformer.h_dec, prefix, idx2,targets2)

        prefix2 = prefix

        if reverted:
            # logits2, lpy2 = self.decode_with_prefix(self.transformer.h_dec, prefix2, idx2,targets2)
            # logits2, lpy2 = self.decode_with_prefix(self.transformer.h_dec, prefix2, idx,targets)
            # logits2, lpy2 = self.decode_with_prefix(self.transformer.h_dec, prefix1, idx,targets)
            logits2, lpy2 = self.decode_with_prefix(self.transformer.h_dec, prefix1, idx2,targets2)


        
        if not self.training:

            loss = lpy2
            # loss = lpy
            loss = -loss.mean() / t2
        else:            
            ### decoder loss + encoder loss

            if self.use_backpred:
                loss = lpy2 + lpy
            else:
                loss = lpy2

            loss = -loss.mean() / t
        return logits, loss      



    def encode_into_suffix(self, blocks, prefix, suffix, idx):
        device = idx.device
        b, t  = idx.size()
        assert t <= self.config.block_size, f"Cannot forward sequence of length {t}, block size is only {self.config.block_size}"

        # ns = self.ns
        # nm = self.nm
        nm = suffix.size()[1]
        nm_a = self.nm_a
        #### decoding the sequence based on the prefix

        ### concating the ending segment to the left of decoder
        pos = torch.arange(0, t, dtype=torch.long, device=device) + 0 # shape (t)
        pos_emb = self.transformer.wpe(pos) # position embeddings of shape (t, n_embd)
        tok_emb = self.transformer.wte(idx) # token embeddings of shape (b, t, n_embd)


        x = tok_emb + pos_emb
        x = torch.cat([prefix, x, suffix ],dim=1)

        for block in blocks:
            x = block(x,x)

        x = x[:,-nm:]

        # x = self.transformer.ln_f(x)
        return x

    def get_init_prefix(self,idx):
        low = self.low
        high = self.high
        nsep = self.nsep
        sep = self.sep
        b,t = idx.size()[:2]
        device = idx.device 
        # b,m = xz_int.shape[:2]

        ns = self.ns
        nm = self.nm
        nm_a = self.nm_a

        pos  = torch.arange(nm+t, nm+t+nm, dtype=torch.long, device=device)  # shape (t)
        idx1 = torch.ones_like(idx[:,:nm]).long()*(self.vmax-1)
        tok_emb = self.transformer.wte(idx1) # token embeddings of shape (b, t, n_embd)
        pos_emb = self.transformer.wpe(pos) # position embeddings of shape (t, n_embd)
        x = tok_emb + pos_emb
        return x



