        nm = self.nm
        nm_a = self.nm_a
        

        # self.prior_logsigma.data = math.log(3.0)*torch.ones_like(self.prior_logsigma.data )
        # self.prior_logsigma_2.data[0] = math.log(2.3)*torch.ones_like(self.prior_logsigma_2.data[0] )
        # self.prior_logsigma_2.data[1] = math.log(0.5)*torch.ones_like(self.prior_logsigma_2.data[1] )
        # i=2;self.prior_logsigma_2.data[i] = math.log(0.5)*torch.ones_like(self.prior_logsigma_2.data[i] )
        # i=3;self.prior_logsigma_2.data[i] = math.log(0.5)*torch.ones_like(self.prior_logsigma_2.data[i] )

        if self.reset and not self.training:

            print([
                self.prior_logsigma_2.exp(),
             ])
            self.reset = False
        if self.training:
            self.reset = True

        x = idx

        idx = idx.repeat((ns,1,1)).reshape((ns*b,t))
        targets = targets.repeat((ns,1,1)).reshape((ns*b,t))
        idx,idx2 = torch.split(idx,t//2,1)
        targets, targets2 = torch.split(targets,t//2,1) 
        t2 = t//2


        icol = torch.ones_like(idx[:,:1]).long()
        prefix   = self.get_init_prefix(idx)
        ### for sequence autoencoding
        idxc = torch.cat([icol*self.token_ae1,idx, icol*self.token_ae2, ], dim=1)
        prefix   = self.encode_into_suffix(self.transformer.h_enc, prefix, prefix,idxc)
        prefix   = self.transformer.comp_out(self.transformer.comp_in(prefix))


        _disabled = self._disabled
        # _disabled = 1;  
        if _disabled:
            print('[DEBUG]Disabling the latent!!!!!!!!------------')
            prefix = prefix.flip((0,))
        prefixc = torch.cat([prefix, self.transformer.wte(icol*self.token_ae3 )],1)
        logits, lpy = self.decode_with_prefix(self.transformer.h_dec, prefixc, idx,targets)




        ### for sequence completion
        prefix   = self.get_init_prefix(idx)
        ### prefixing auto-completion token 
        idxc = torch.cat([icol*self.token_comp1, idx, icol*self.token_comp2, ], dim=1)
        prefix   = self.encode_into_suffix(self.transformer.h_enc, prefix, prefix,idxc)
        prefix   = self.transformer.comp_out(self.transformer.comp_in(prefix))

        _disabled = self._disabled
