class LGT364B(LGT355H):


    '''
    prior: tfm
    latent: clipped xz

    Kernellising the MLP activation function s(k) to be rank 1 bilinear kernels
    same as GPT102G but introducing a gaussian approximation of bernoulli variables
    Preprocessed token
    '''
    logsigma = math.log(0.5)

    def __init__(self, config):
        super(GPT,self).__init__()

        assert config.vocab_size is not None
        assert config.block_size is not None
        config = copy.copy(config)
        self.config = config

        vmax = config.vocab_size+500+10
        # nm = 10
        self.vmax = vmax
        self.nm = config.nm = nm = 4
        self.ns = 3
        self.nm_a = nm_a = config.n_embd
        self.nm_a = config.nm_a = nm_a = 24 ### R2
        self.nk = nk = 200

        self.low  = config.low  = low  = -3.0
        self.high = config.high = high =  3.0
        # self.nsep = config.nsep = 5
        self.nsep = config.nsep = nsep = 120
        self.sep = (self.high -self.low)/self.nsep
        # self.sep = 0.05
        self.lseg = config.lseg = lseg = 32

        h_dec = nn.ModuleList([Block235(config) for _ in range(config.n_layer)])
        self.transformer = nn.ModuleDict(dict(
            wte = nn.Embedding(vmax, config.n_embd),
            wve = nn.Embedding(nk, config.n_embd),
            wpe = nn.Embedding(config.block_size+nm*2, config.n_embd),
            wpe2 = nn.Embedding(config.block_size+nm*2, config.n_embd),

            comp_in = nn.Linear(config.n_embd, nm_a,bias=False),
            comp_out = nn.Linear(nm_a,config.n_embd, bias=False),

            drop = nn.Dropout(config.dropout),
            
            # h0 = nn.ModuleList([Block140(config) for _ in range(1)]),

            ### for backprediction
            # h_enc = nn.ModuleList([Block235(config) for _ in range(config.n_layer//2)]),
            # h_enc = nn.ModuleList([Block235(config,is_causal=False) for _ in range(config.n_layer//2)]),
            h_enc = nn.ModuleList([Block235(config,is_causal=True) for _ in range(config.n_layer)]),
            h_dec = h_dec,
            h_dec2 = h_dec,
            # h_enc = h_dec,

            # h_ar = nn.ModuleList([Block235(config) for _ in range(config.n_layer)] ),
            # hlast = Block231(config),
            ln_f = LayerNorm(config.n_embd, bias=config.bias),
            ln_f2 = LayerNorm(config.n_embd, bias=config.bias),
            ln_f3 = LayerNorm(config.n_embd, bias=config.bias),
        ))
        self.transformer.comp_in.weight = nn.Parameter(torch.eye(config.n_embd)[:nm_a],requires_grad=False)
        self.transformer.comp_out.weight = nn.Parameter(torch.eye(config.n_embd)[:,:nm_a],requires_grad=False)
        # self.encoder = nn.Linear(config.block_size*config.n_embd, nm_a, bias=False)
        self.lm_head = nn.Linear(config.n_embd, vmax, bias=False)
        # self.lm_norm = nn.Linear(1, config.vocab_size, bias=True)
        # self.lm_null = nn.Linear(1, config.vocab_size, bias=False)
        # self.norm_m = nn.Parameter(torch.tensor(7.5))
        ### precision of the gaussian distrib
        self.norm_w = nn.Parameter(torch.tensor(0.))
        # self.norm_b = nn.Parameter(torch.tensor(0.))

        # with weight tying when using torch.compile() some warnings get generated:
        # "UserWarning: functional_call was passed multiple values for tied weights.
        # This behavior is deprecated and will be an error in future versions"
        # not 100% sure what this is, so far seems to be harmless. TODO investigate
        self.transformer.wte.weight = self.lm_head.weight # https://paperswithcode.com/method/weight-tying

        # self.prior_h = prior_h = 100
        self.prior_h = prior_h = config.n_embd
        self.norm_w = nn.Parameter(torch.tensor(0.))

        # self.prior_mean = nn.Linear(nk, nm_a*nm, bias=False)
        self.prior_ar = nn.Linear(nm, nm_a*nm_a, bias=False)
        self.prior_logsigma_2 = nn.Parameter(torch.tensor([math.log(2.0),math.log(1.0),math.log(1.0),math.log(1.0)]))

        # self.prior_gru  = nn.GRU(nm_a, prior_h, 1, batch_first=True)
        # self.prior_proj = nn.Linear(prior_h*nsep, nm*nm_a,bias=True)
        self.prior_ln   = LayerNorm(prior_h, bias=config.bias)




        # init all weights
        self.apply(self._init_weights)
        # apply special scaled init to the residual projections, per GPT-2 paper
        for pn, p in self.named_parameters():
            if pn.endswith('c_proj.weight'):
                torch.nn.init.normal_(p, mean=0.0, std=0.02/math.sqrt(2 * config.n_layer))

        # report number of parameters
        print("number of parameters: %.2fM" % (self.get_num_params()/1e6,))
        self.reset = True


        # self.prior_logsigma = nn.Parameter(torch.tensor(math.log(0.1)))
        # self.post_logsigma = nn.Parameter(torch.tensor(math.log(0.1)))
        self.logsigma = math.log(0.5)

        self._disabled=0
        # self._disabled=1
        self.use_backpred=0


    def ns2vecs(self,ns,device):
        # idxa,idxb = ns2vecs(ns)
        idxn = torch.arange(ns,device=device)
        idxa = self.vmax - 1 - idxn
        idxb = self.vmax - 1 - (idxn + ns)
        return idxa,idxb

    def get_log_prior(self,ns,device):
        return math.log(1./ns)


    def forward(self, idx, targets=None):
        '''
        the first token of index is masked to vmax-2
        '''
        if self.training:
            self.reset = True

        device = idx.device
        b, t = idx.size()
        assert t <= self.config.block_size, f"Cannot forward sequence of length {t}, block size is only {self.config.block_size}"
        low = self.low
        high = self.high
        nsep = self.nsep
        sep = self.sep

        lseg = self.lseg

        nseg = t//self.lseg
        assert nseg  == 2,(t,lseg,nseg)
        ns = 10
        # ns = 20
        assert t%self.lseg==0, f"cannot split into segment ({t} // {self.lseg})"

        x = idx

        idx = idx.repeat((ns,1,1)).reshape((ns,b,nseg,lseg))
        targets = targets.repeat((ns,1,1)).reshape((ns,b,nseg,lseg))
        idxcol = torch.ones_like(idx[:,:,:1,:1]).long()
        idxa,idxb=self.ns2vecs(ns,idx.device)

        prefixs = torch.cat([idxb[0:1,None,None,None]*idxcol,idxb[0:1,None,None,None]*idxcol],dim=2)
        idx0 = idx
        idx = torch.cat([idx, prefixs, ],dim=3).reshape(ns*b,-1)

        targets_fill = torch.cat([-1*idxcol,-1*idxcol],dim=2)
        targets = torch.cat([targets_fill,targets],dim=3).reshape(ns*b,-1)

        ### concating the ending segment to the left of decoder
        tx = idx.shape[1]
        pos = torch.arange(0, tx, dtype=torch.long, device=device) + 0 # shape (t)
        pos_emb = self.transformer.wpe(pos) # position embeddings of shape (t, n_embd)
        tok_emb = self.transformer.wte(idx) # token embeddings of shape (b, t, n_embd)
        input_emb = tok_emb + pos_emb       
        input_emb0 = input_emb 
    
        blocks = self.transformer.h_enc
        x = input_emb
        for block in blocks:
            x = block(x,x)
        x = self.transformer.ln_f3(x)
        output_emb = x



        ne = self.config.n_embd
        # input_emb = torch.
        nk = self.nk
        vatt = output_emb.reshape(ns,b,nseg,lseg+1,-1)[0,:,:,-1:,:]
        vatt = vatt.matmul(self.transformer.wve.weight.T)

        ## debug
        # vatt = torch.zeros_like(vatt); self.print_once('[DEBUG] disabled latent---------------')
        vatt = torch.flip(vatt,(0,)); self.print_once('[DEBUG] disabled latent---------------')

        topk = 1
        if topk:
            v = vatt.topk(topk,dim=-1)[0].min(-1)[0]
            vatt = vatt.masked_fill(vatt<v.unsqueeze(-1),float('-inf'))
        vatt = vatt.softmax(-1)
        # att = ;
        dist = torch.distributions.categorical.Categorical(probs=vatt)
        idxk = dist.sample((ns,))

        ### STE replacement
        veck = (torch.eye(nk,device=idx.device)[idxk,:].reshape(ns,b,nseg,1,nk) - vatt[None]).detach() + vatt[None]
        veck = veck.matmul(self.transformer.wve.weight)

        input_emb = torch.cat([veck, input_emb0.reshape(ns,b,nseg,1+lseg,ne)[:,:,:,:-1]],3)
        input_emb = input_emb.reshape(ns*b,-1,ne)
        

        logits, lpy21 = self.decode_with_prefix(self.transformer.h_dec, idx, input_emb, targets)
        lp2s = lpy21.reshape(ns,b,1)
        lp2s = lp2s + self.get_log_prior(self.nk,device)*nseg
        # lpy2,idxk = torch.max(lp2s, dim=0)
        # lpy2 = lp2s.mean(0)

        if not self.training:
            lpy2 = lp2s.logsumexp(0)
        else:
            # lpy2 = lp2s.logsumexp(0)
            lpy2 = lp2s.mean(0)            
        # logsumexp(0)
        # print(idxk)
        lpy1 = lpy2



        reverted = 0
        # reverted = 1
        if reverted:
            print('[reverted]')
            # prefix = prefix2
            prefix = prefix1 
            prefixc = torch.cat([self.transformer.wte(idxcol*self.token_comp2), prefix, self.transformer.wte(idxcol*self.token_comp3),],1 )
            # prefixc = torch.cat([self.transformer.wte(idxcol*self.token_ae2), prefix, self.transformer.wte(idxcol*self.token_ae3),] ,1)
            # logits2, lpy2 = self.decode_with_prefix(self.transformer.h_dec, prefixc, idx2,targets2)

            logits, lpy2 = self.decode_with_prefix(self.transformer.h_dec, prefixc, idx,targets)

        # if 1:
        if 0:
            print()
            print([lp1s.softmax(1).mean(0), lp2s.softmax(1).mean(0)] )


        if not self.training:

            loss = lpy2
            loss = -loss.mean() / t
            # loss = loss/b
        else:            
            ### decoder loss + encoder loss

            if self.use_backpred:
                loss = lpy2 + lpy1
            else:
                loss = lpy2

            loss = -loss.mean() / t
        if self.reset and not self.training:

            print([
                # self.prior_logsigma_2.exp(),
             ])
            self.reset = False

        return logits, loss      





    def decode_with_prefix(self, blocks, idx, input_emb, targets, sum=1):
        idx=input_emb
        device = idx.device
        b, t  = idx.size()[:2]
        # assert t <= self.config.block_size, f"Cannot forward sequence of length {t}, block size is only {self.config.block_size}"

        #### decoding the sequence based on the prefix



        x = input_emb
        for block in blocks:
            x = block(x,x)

        x = self.transformer.ln_f(x)


        logits = self.lm_head(x)
        lpy = None
        if targets is not None:
            loss = F.cross_entropy(logits.view(-1, logits.size(-1)), targets.reshape(-1), ignore_index=-1,reduction='none')
            lpy = -loss.reshape((b,-1,t))
            if sum==1:
                lpy = lpy.sum(-1)        
        return logits,lpy

