        pos_emb = self.transformer.wpe(pos)[None].repeat(ns*b,1,1) # position embeddings of shape (t, n_embd)
        tok_emb = self.transformer.wte(idx) # token embeddings of shape (b, t, n_embd)
        tok_emb0 = tok_emb.reshape(ns,b,nseg,lseg+7,ne)
