        input_emb0 = input_emb 
    
        blocks = self.transformer.h_enc
        x = input_emb
        for block in blocks:
            x = block(x,x)
        x = self.transformer.ln_f3(x)
        output_emb = x



        vatt = output_emb.reshape(ns,b,nseg,lseg+7,-1)[0,:,:,-2:,:]
        seg_emb = tok_emb0[0,:,:,4:4+lseg]
