        vatt = vatt.masked_fill(vatt<v, float('-inf'))
        vatt = vatt.softmax(-1)
        # print((vatt.mean((0,1,))*1000).long().cpu().numpy())
        # att = ;
        dist = torch.distributions.categorical.Categorical(probs=vatt)
        idxk = dist.sample((ns,))
        idxk = idxk.reshape(ns,b,nseg,nm,)
