        self.prior_ar = nn.Linear(nm, nm_a*nm_a, bias=False)
        self.prior_logsigma_2 = nn.Parameter(torch.tensor([math.log(2.0),math.log(1.0),math.log(1.0),math.log(1.0)]))

        # self.prior_gru  = nn.GRU(nm_a, prior_h, 1, batch_first=True)
        # self.prior_proj = nn.Linear(prior_h*nsep, nm*nm_a,bias=True)
        self.prior_ln   = LayerNorm(prior_h, bias=config.bias)




        # init all weights
        self.apply(self._init_weights)
