        idxa,idxb=self.ns2vecs(ns,idx.device)
        idxcol2 = torch.ones_like(idx[:,:,:,:1]).long()


        
        idx0 = idx
        idx = torch.cat([ 
            idx, 
            idxcol2*self.token_v11,
             ],dim=3).reshape(ns*b,-1)


        ### concating the ending segment to the left of decoder
        tx = idx.shape[1]
        pos = torch.arange(0, tx, dtype=torch.long, device=device) + 0 # shape (t)
        pos_emb = self.transformer.wpe(pos)[None].repeat(ns*b,1,1) # position embeddings of shape (t, n_embd)
        tok_emb = self.transformer.wte(idx) # token embeddings of shape (b, t, n_embd)
        tok_emb0 = tok_emb.reshape(ns,b,nseg,lseg+1,ne)
        input_emb = tok_emb + pos_emb       
        input_emb0 = input_emb 
    
        blocks = self.transformer.h_enc
        x = input_emb
        for block in blocks:
            x = block(x,x)
        x = self.transformer.ln_f3(x)
        output_emb = x
        output_emb = output_emb.reshape(ns,b,nseg,lseg+1,ne)
        vatt = output_emb

        targ_emb = self.transformer.wte(targets).reshape(ns,b,t,ne)

        # print(vatt.shape,targ_emb.shape)
        ### calculate the posterior prob and sample from the posterior

        ### prior graphical model
        vatt = torch.einsum('bpe,bte->btp',output_emb[0,:,:,0,:], self.w_prior(output_emb[0,:,:,0,:]))
        vatt = vatt.masked_fill(att_mask[None]== 0, float('-inf'))
        vprior = vatt.log_softmax(-1)

        ### posterior graphical model
        vatt = torch.einsum('bpe,bte->btp', self.w_post(output_emb[0,:,:,0,:]), (pos_emb.reshape(ns,b,-1,ne)[:,:,::2]+targ_emb)[0])
        vatt = vatt.masked_fill(att_mask[None]== 0, float('-inf'))



