        # vatt = self.pos_prior.weight.reshape(1,t,t,1)*200
        vatt = vatt.masked_fill(att_mask[None,:,:,None]== 0, float('-inf'))
        vatt = vatt.masked_fill(idxt[None,:,None,None]!=idxt[None,None,:,None], float('-inf')); self.print_once('[DEBUG] using diagonal ---------------')
        vprior = vatt.reshape(b,t,-1).log_softmax(-1).reshape(vatt.shape)

        ### posterior graphical model
        vatt = torch.einsum('bpve,bte->btpv', self.transformer.ln_f(output_emb_vs),  self.transformer.ln_f(targ_emb[0]))
        # vatt = torch.einsum('bpve,bte->btpv', output_emb_vs,  targ_emb[0])
        vatt = vatt.masked_fill(att_mask[None,:,:,None]== 0, float('-inf'))
        # vatt = 0.05*vatt + vprior
        vatt = vatt + vprior

        ## debug
        # vatt = torch.zeros_like(vatt); self.print_once('[DEBUG] disabled latent---------------')
        # vatt = torch.flip(vatt,(0,)); self.print_once('[DEBUG] flipping latent---------------')
        vatt = vatt.masked_fill(idxt[None,:,None,None]!=idxt[None,None,:,None], float('-inf')); self.print_once('[DEBUG] using diagonal ---------------')
        vprior = vprior.masked_fill(idxt[None,:,None,None]!=idxt[None,None,:,None], float('-inf')); 
        

        vatt = vatt.reshape(b,t,-1)
        vprior = vprior.reshape(b,t,-1)

        self.print_once((vprior.exp()[:1].mean((0,)).reshape(t,t,-1).transpose(-1,0)[:,:10,:10]*1000).long())

        self.print_once((vatt[:1].softmax(-1).mean((0,)).reshape(t,t,-1).transpose(-1,0)[:,:10,:10]*1000).long())
        self.print_once(((vatt[:1].softmax(-1)-vprior.exp()[:1]).mean((0,)).reshape(t,t,-1).transpose(-1,0)[:,:10,:10]*1000).long())

        # vatt = vprior; self.print_once('[DEBUG] using prior---------------')

        topk = self.topk
        if topk>0:
            v = vatt.topk(k=topk,dim=-1)[0].min(-1)[0].unsqueeze(-1)
            vatt  = vatt.masked_fill(vatt<v, float('-inf'))
        vattp = vatt.softmax(-1)
        vattp = vattp[None]

        dist = torch.distributions.categorical.Categorical(probs=vattp)
        idxk = dist.sample((ns,))
        idxk = idxk.reshape(ns,b,t)


        ### STE replacement
        veck = torch.eye(t*nopt,device=idx.device)[idxk,:]
        veck = (veck- vattp).detach() + vattp
        
        
        veck_emb = torch.einsum('nbtp,bpe->nbte', veck.detach(),  output_emb_vs.reshape(b,-1,ne))
        input_emb = veck_emb.reshape(ns*b,t,ne)

        idxn = torch.arange(ns,device=device)
        idxb = torch.arange(b,device=device)
        lp_prior = vprior[idxb[None,:,None],idxt[None,None,:],idxk].sum(-1)        

        input_emb = self.transformer.ln_f(input_emb)

        
        logits, lpy21 = self.decode_with_prefix(self.transformer.h_dec, idx, input_emb, targets)
        lp2s = lpy21.reshape(ns,b,1)
