        targets = targets.repeat((ns,1,1)).reshape((ns,b,t))

        
        idx0 = idx
        idx = idx.reshape(ns*b,-1)

        tx = t
        pos = torch.arange(0, tx, dtype=torch.long, device=device) + 0 # shape (t)
        pos_emb = self.transformer.wpe(pos)[None].repeat(ns*b,1,1) # position embeddings of shape (ns*b, t, n_embd)
        tok_emb = self.transformer.wte(idx) # token embeddings of shape (b, t, n_embd)
        tok_emb0 = tok_emb.reshape(ns,b,t,ne)
        input_emb = (tok_emb + pos_emb ).reshape(ns,b,t,ne)[0]      
    
