        input_emb = (tok_emb + pos_emb ).reshape(ns,b,t,ne)[0]      
    
        blocks = self.transformer.h_enc
        x = input_emb
        for block in blocks:
            x = block(x,x)
        x = self.transformer.ln_f3(x)
        output_emb = x
        output_emb = output_emb.reshape(b,t,ne)
        vatt = output_emb

        targ_emb = self.transformer.wte(targets).reshape(ns,b,t,ne)

        ### prior graphical model
        x1 = self.transformer.h_post[0](x,x)
        output_emb_emit_v = self.w_emit_v(x1)
        output_emb_emit_k = self.w_emit_k(x1)

