class LGT433D(LGT001):


    '''
    prior: tfm
    latent: clipped xz

    Kernellising the MLP activation function s(k) to be rank 1 bilinear kernels
    same as GPT102G but introducing a gaussian approximation of bernoulli variables
    Preprocessed token
    '''
    logsigma = math.log(0.5)

    def __init__(self, config):
        super(GPT,self).__init__()

        assert config.vocab_size is not None
        assert config.block_size is not None
        config = copy.copy(config)
        self.config = config
        ne = config.n_embd

        vmax = config.vocab_size+500+10
        # nm = 10
        self.ns = 5
        # self.ns = 10
        self.vmax = vmax
        self.lseg = config.lseg = lseg = 1

        h_dec = nn.ModuleList([Block235(config) for _ in range(config.n_layer)])
        self.transformer = nn.ModuleDict(dict(
            wte = nn.Embedding(vmax, config.n_embd),
            # wve = nn.Embedding(nk, config.n_embd),
            wpe = nn.Embedding(config.block_size*3, config.n_embd),
            wpe2 = nn.Embedding(config.block_size*3, config.n_embd),
            drop = nn.Dropout(config.dropout),
            
            ### for backprediction
            h_dec = h_dec,
            h_enc = h_dec,
            h_post = nn.ModuleList([nn.Linear(config.n_embd,config.n_embd) for _ in range(config.n_layer)]),
            # h_enc = h_post,

            ln_f = LayerNorm(config.n_embd, bias=config.bias),
            ln_f2 = LayerNorm(config.n_embd, bias=config.bias),
            ln_f3 = LayerNorm(config.n_embd, bias=config.bias),
        ))
        self.lm_head = nn.Linear(config.n_embd, vmax, bias=False)

        ### precision of the gaussian distrib
        self.w_emit_v = nn.Linear(ne,ne,bias=False)
        self.w_emit_k = nn.Linear(ne,ne,bias=False)
        self.w_emit2_v = nn.Linear(ne,ne,bias=False)
        self.w_emit2_k = nn.Linear(ne,ne,bias=False)
        self.w_emit3_v = nn.Linear(ne,ne,bias=False)
        self.w_emit3_k = nn.Linear(ne,ne,bias=False)
        # self.w_copy_v = nn.Linear(ne,ne,bias=False)
        # self.w_copy_k = nn.Linear(ne,ne,bias=False)
        self.pos_prior = nn.Linear(1,config.block_size*config.block_size,bias=True)
        # self.w_post  = nn.Linear(ne,ne,bias=False)

        # with weight tying when using torch.compile() some warnings get generated:
        # "UserWarning: functional_call was passed multiple values for tied weights.
        # This behavior is deprecated and will be an error in future versions"
        # not 100% sure what this is, so far seems to be harmless. TODO investigate
        self.transformer.wte.weight = self.lm_head.weight # https://paperswithcode.com/method/weight-tying

        # init all weights
        self.apply(self._init_weights)
        # apply special scaled init to the residual projections, per GPT-2 paper
        for pn, p in self.named_parameters():
            if pn.endswith('c_proj.weight'):
                torch.nn.init.normal_(p, mean=0.0, std=0.02/math.sqrt(2 * config.n_layer))

        # report number of parameters
        print("number of parameters: %.2fM" % (self.get_num_params()/1e6,))
        self.reset = True



        self._disabled=0
        # self._disabled=1
        self.use_backpred=0
        self.topk = 1



    def get_log_prior(self,ns,device):
        return math.log(1./ns)


    def forward(self, idx, targets=None):
        '''
        the first token of index is masked to vmax-2
        '''
        if self.training:
            self.reset = True

        device = idx.device
        b, t = idx.size()
        assert t <= self.config.block_size, f"Cannot forward sequence of length {t}, block size is only {self.config.block_size}"

        lseg = self.lseg

        nseg = t//self.lseg
        ns = self.ns
        assert t%self.lseg==0, f"cannot split into segment ({t} // {self.lseg})"


        att_mask = torch.ones((t,t),device=device).bool()
        ### (tc,tp)
        att_mask      = torch.tril(att_mask, diagonal=0)
        idxt = torch.arange(t,device=device)

        x = idx
        ne = self.config.n_embd

        idx = idx.repeat((ns,1,1)).reshape((ns,b,t))
        targets = targets.repeat((ns,1,1)).reshape((ns,b,t))

        
        idx0 = idx
        idx = idx.reshape(ns*b,-1)

        tx = t
        pos = torch.arange(0, tx, dtype=torch.long, device=device) + 0 # shape (t)
        pos_emb = self.transformer.wpe(pos)[None].repeat(ns*b,1,1) # position embeddings of shape (ns*b, t, n_embd)
        tok_emb = self.transformer.wte(idx) # token embeddings of shape (b, t, n_embd)
        tok_emb0 = tok_emb.reshape(ns,b,t,ne)
        input_emb = (tok_emb + pos_emb ).reshape(ns,b,t,ne)[0]      
    
        blocks = self.transformer.h_enc
        x = input_emb
        for block in blocks:
            x = block(x,x)
        x = self.transformer.ln_f3(x)
        output_emb = x
        output_emb = output_emb.reshape(b,t,ne)
        vatt = output_emb

        targ_emb = self.transformer.wte(targets).reshape(ns,b,t,ne)
        ne = self.config.n_embd
        ### prior graphical model
        x1 = self.transformer.h_post[0](x)
        output_emb_emit_v = self.w_emit_v(x1)
        output_emb_emit_k = self.w_emit_k(output_emb)/ne**0.5

        x2 = self.transformer.h_post[1](x)
        output_emb_emit2_v = self.w_emit2_v(x2)
        output_emb_emit2_k = self.w_emit2_k(output_emb)/ne**0.5

        x3 = self.transformer.h_post[2](x)
        output_emb_emit3_v = self.w_emit3_v(x3)
        output_emb_emit3_k = self.w_emit3_k(output_emb)/ne**0.5


        # output_emb_vs = torch.stack([output_emb_emit_v, output_emb_copy_v],2)
        # output_emb_ks = torch.stack([output_emb_emit_k, output_emb_copy_k],2)

        output_emb_vs = torch.stack([output_emb_emit_v, output_emb_emit2_v, output_emb_emit3_v],2)
        output_emb_ks = torch.stack([output_emb_emit_k, output_emb_emit2_k, output_emb_emit3_k],2)
        nopt = output_emb_ks.shape[2]

        vatt = torch.einsum('bpve,bte->btpv', output_emb_ks, output_emb)
        # vatt = self.pos_prior.weight.reshape(1,t,t,1)*500
        # vatt = self.pos_prior.weight.reshape(1,t,t,1)*200
        vatt = vatt.masked_fill(att_mask[None,:,:,None]== 0,0)
        vatt = vatt.masked_fill(idxt[None,:,None,None]!=idxt[None,None,:,None],0.); self.print_once('[DEBUG] using diagonal ---------------')
        self.print_once(('----raw prior'))
        self.print_once((1000*vatt.reshape(b,t,t,-1)[:1].mean((0,)).reshape(t,t,-1).transpose(-1,0)[:,:10,:10]).long())
        vatt = vatt.masked_fill(att_mask[None,:,:,None]== 0, float('-inf'))
        vatt = vatt.masked_fill(idxt[None,:,None,None]!=idxt[None,None,:,None], float('-inf')); self.print_once('[DEBUG] using diagonal ---------------')
        vprior = vatt.reshape(b,t,-1)
        vprior = vprior.log_softmax(-1).reshape(vatt.shape)

        ### posterior graphical model
        # vatt = torch.einsum('bpve,bte->btpv', self.transformer.ln_f(output_emb_vs),  self.transformer.ln_f(targ_emb[0]))
        vatt = torch.einsum('bpve,bte->btpv', self.transformer.ln_f(output_emb_vs),  (targ_emb[0]))
        vatt = vatt.masked_fill(att_mask[None,:,:,None]== 0,0)
        vatt = vatt.masked_fill(idxt[None,:,None,None]!=idxt[None,None,:,None],0.); self.print_once('[DEBUG] using diagonal ---------------')
        self.print_once(('----raw posterior'))
        self.print_once((1000*vatt.reshape(b,t,t,-1)[:1].mean((0,)).reshape(t,t,-1).transpose(-1,0)[:,:10,:10]).long())
        # vatt = torch.einsum('bpve,bte->btpv', output_emb_vs,  targ_emb[0])
        vatt = vatt.masked_fill(att_mask[None,:,:,None]== 0, float('-inf'))
        # vatt = 0.05*vatt + vprior
        vatt = vatt 

        ## debug
        # vatt = torch.zeros_like(vatt); self.print_once('[DEBUG] disabled latent---------------')
        # vatt = torch.flip(vatt,(0,)); self.print_once('[DEBUG] flipping latent---------------')
        vatt = vatt.masked_fill(idxt[None,:,None,None]!=idxt[None,None,:,None], float('-inf')); self.print_once('[DEBUG] using diagonal ---------------')
        vprior = vprior.masked_fill(idxt[None,:,None,None]!=idxt[None,None,:,None], float('-inf')); 
        

        vatt = vatt.reshape(b,t,-1)
        vprior = vprior.reshape(b,t,-1)

        self.print_once((vprior.exp()[:1].mean((0,)).reshape(t,t,-1).transpose(-1,0)[:,:10,:10]*1000).long())

        self.print_once((vatt[:1].softmax(-1).mean((0,)).reshape(t,t,-1).transpose(-1,0)[:,:10,:10]*1000).long())
        self.print_once(((vatt[:1].softmax(-1)-vprior.exp()[:1]).mean((0,)).reshape(t,t,-1).transpose(-1,0)[:,:10,:10]*1000).long())

        # vatt = vprior; self.print_once('[DEBUG] using prior---------------')

        topk = self.topk
        # topk = 1
        if topk>0:
            v = vatt.topk(k=topk,dim=-1)[0].min(-1)[0].unsqueeze(-1)
            vatt  = vatt.masked_fill(vatt<v, float('-inf'))
        vattp = vatt.softmax(-1)
        vattp = vattp[None]

        dist = torch.distributions.categorical.Categorical(probs=vattp)
        idxk = dist.sample((ns,))
        idxk = idxk.reshape(ns,b,t)


        ### STE replacement
        veck = torch.eye(t*nopt,device=idx.device)[idxk,:]
        veck = (veck- vattp).detach() + vattp
        
        
        veck_emb = torch.einsum('nbtp,bpe->nbte', veck.detach(),  output_emb_vs.reshape(b,-1,ne))
        input_emb = veck_emb.reshape(ns*b,t,ne)

        idxn = torch.arange(ns,device=device)
        idxb = torch.arange(b,device=device)
        lp_prior = vprior[idxb[None,:,None],idxt[None,None,:],idxk].sum(-1)        

        input_emb = self.transformer.ln_f(input_emb)

        
        logits, lpy21 = self.decode_with_prefix(self.transformer.h_dec, idx, input_emb, targets)
        lp2s = lpy21.reshape(ns,b,1)
        lp2s = lp2s + lp_prior.unsqueeze(-1)
        ### simple fixed prior 
        # lp2s = lp2s - torch.arange(1,t+1,device=device).log().sum()
        # lp2s = lp2s + self.get_log_prior(self.vmax,device)*nseg*nm


        if not self.training:
            lpy2 = lp2s.logsumexp(0)
        else:
            lpy2 = lp2s.mean(0)            
        lpy1 = lpy2


        if not self.training:
            loss = lpy2
            loss = -loss.mean() / t
            # loss = loss/b
        else:            
            ### decoder loss + encoder loss
            loss = lpy2
            loss = -loss.mean() / t

        if self.reset and not self.training:
            print([
                # self.prior_logsigma_2.exp(),
             ])
            self.reset = False

        return logits, loss      


    def decode_with_prefix(self, blocks, idx, input_emb, targets, sum=1):
        idx=input_emb
        device = idx.device
        b, t  = idx.size()[:2]
        # assert t <= self.config.block_size, f"Cannot forward sequence of length {t}, block size is only {self.config.block_size}"

        #### decoding the sequence based on the prefix
        x = input_emb

        logits = self.lm_head(x)
        lpy = None
        if targets is not None:
            loss = F.cross_entropy(logits.view(-1, logits.size(-1)), targets.reshape(-1), ignore_index=-1,reduction='none')
            lpy = -loss.reshape((b,-1,t))
            if sum==1:
                lpy = lpy.sum(-1)        
        return logits,lpy

        



