        # not 100% sure what this is, so far seems to be harmless. TODO investigate
        self.transformer.wte.weight = self.lm_head.weight # https://paperswithcode.com/method/weight-tying

        # self.prior_h = prior_h = 100
        self.prior_h = prior_h = config.n_embd
        self.norm_w = nn.Parameter(torch.tensor(0.))

        self.nk = nk = 1
        # self.prior_mean = nn.Linear(nk, nm_a*nm, bias=False)
        self.prior_ar = nn.Linear(nm, nm_a*nm_a, bias=False)
        self.prior_logsigma_2 = nn.Parameter(torch.tensor([math.log(2.0),math.log(1.0)]))

