        ### prefixing auto-completion token 
        idxc = torch.cat([idxcol*self.token_comp1,idx, idxcol*self.token_comp2,], dim=1)
        prefix   = self.encode_into_suffix(self.transformer.h_dec, prefix, prefix,idxc)
        prefix   = self.transformer.comp_out(self.transformer.comp_in(prefix))
        if _disabled:
            self.print_once('[DEBUG]Disabling the latent!!!!!!!!------------')
            prefix = prefix.flip((0,))

        prefixc = torch.cat([self.transformer.wte(idxcol*self.token_comp2), prefix, self.transformer.wte(idxcol*self.token_comp3),],1 )
        prefix2 = prefix
        prefixc2 = prefixc



        ### for sequence completion
