        # idxb = torch.arange(ns*b,device=device)[:,None,None]
        # idxt = torch.arange(t,device=device)[None,:,None]
        _,idxk = latp.max(-1)

        veck = (torch.eye(nm_a,device=device)[idxk,:] - latp).detach() + latp
        xx = veck.matmul(self.transformer.kvec.weight)

        # x = tok_emb + xx + pos_emb

        prefix = xx
        ### resampled representation q( z|d )
        ### STE estimator

        _disabled = self._disabled
        # _disabled = 1;  
        if _disabled:
            self.print_once('[DEBUG]Disabling the latent!!!!!!!!------------')
            ### quality checking the noise
            # assert 0
            prefix = prefix.flip((0,))
            # prefix = prefix[0:1] * torch.ones_like(prefix[:,:1,:1])


        ### decoder loss
        logits, lpy = self.decode_with_prefix(self.transformer.h_dec, prefix, idx, targets,sum=1)
        lpy = lpy - math.log(nm_a)*nm
        lpy1,lpy2 = torch.split(lpy, ns*b//2, dim=0)
        self.print_once(torch.stack([lpy1,lpy2],0).mean(1).squeeze(-1))

        ### adding                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
        if not self.training:
            loss = (lpy1+lpy2)/2
            loss = -loss.mean() / t
        else:            
            ### decoder loss + encoder loss
            loss = (lpy1+lpy2)/2
            loss = -loss.mean() / t

        if self.reset and not self.training:
            self.reset = False

        return logits, loss      





