def np_pca(X, n_components=None):
    """
    Perform Principal Component Analysis (PCA) on the dataset X.
    
    :param X: {array-like}, shape (n_samples, n_features)
            The training input samples. Internally, it will be converted to
            `dtype=np.float64`.
    :param n_components: int, None or 'mle', default=None
        Number of components to keep. If None, all components are kept.
        If 'mle', Minka's MLE is used to guess the dimension.
    :return: X_pca: array-like, shape (n_samples, n_components)
        The transformed data.
    :return: pca_components: array-like, shape (n_features, n_components)
        The principal components.
    """
    # Center the data
    X = X - np.mean(X, axis=0)
    
    # Calculate the covariance matrix
    cov_matrix = np.cov(X, rowvar=False)
    
    # Calculate eigenvalues and eigenvectors
    eigenvalues, eigenvectors = np.linalg.eigh(cov_matrix)
    
    # Sort the eigenvectors by decreasing eigenvalues
    sorted_indices = np.argsort(eigenvalues)[::-1]
    sorted_eigenvectors = eigenvectors[:, sorted_indices]
    
    # Choose the first n_components
    if n_components is not None:
        sorted_eigenvectors = sorted_eigenvectors[:, :n_components]
    
    # Transform the data
    X_pca = X @ sorted_eigenvectors
    
    return X_pca, sorted_eigenvectors


