    def forward(self, idx, targets=None):
        '''
        the first token of index is masked to vmax-2
        '''

        if self.training:
            self.reset = True


        device = idx.device
        b, t = idx.size()
        assert t <= self.config.block_size, f"Cannot forward sequence of length {t}, block size is only {self.config.block_size}"
        low = self.low
        high = self.high
        nsep = self.nsep
        sep = self.sep

        ns = self.ns
        nm = self.nm
        nm_a = self.nm_a
        

        if self.training:
            self.reset = True



        idx1,idx2 = torch.split(idx,t//2,1)
        targets1, targets2 = torch.split(targets,t//2,1) 
        idx3 = torch.cat([idx1,idx1],1)
        targets3 = torch.cat([targets1,targets1],1)

        idx = torch.cat([idx,idx3],0)
        targets = torch.cat([targets,targets3],0)
        b = b*2

        ### predict the last token only

        idx = idx.repeat((ns,1,1)).reshape((ns*b,t))
        targets = targets.repeat((ns,1,1)).reshape((ns*b,t))

        idx1 = torch.cat([idx, torch.ones((ns*b,nm),device=device).long()*(self.vmax-1)],dim=1)

        pos  = torch.arange(0,t+nm, dtype=torch.long, device=device)  # shape (t)
        targ_emb = self.transformer.wte(targets) # token embeddings of shape (b, t, n_embd)
        tok_emb = self.transformer.wte(idx1)     # token embeddings of shape (b, t, n_embd)
        pos_emb = self.transformer.wpe(pos)      # position embeddings of shape (t, n_embd)
        x = tok_emb + pos_emb

        for block in self.transformer.h_enc:
            x = block(x,x)
        x = self.transformer.ln_f2(x)
        x = x[:,-nm:]

        ### truncating the output to desired dimension
        xout = x
        latent = self.transformer.comp_in(x)
        # latent = latent + (torch.rand_like(latent)-0.5)*0.1
        low  = self.low
        high = self.high
        sep  = self.sep
        lpe = -5. * (latent - latent.clip(low,high)).square().sum(-1).sum(-1,keepdims=True)
        xint = ((latent.clip(low, high-0.5*sep) - low )//sep)
        # latent = ((xint + torch.rand_like(xint)) * sep + low - latent).detach() + latent
        latent = ((xint + 0.5) * sep + low - latent).detach() + latent

        self.print_once([latent.shape,sep,low,high])
        # self.print_once(torch.stack([xint.max(),xint.min()],0))
        self.print_once(torch.stack([latent.max(),latent.min()],0))
        self.print_once(torch.stack([tok_emb.max(),tok_emb.min()],0))
        xx = self.transformer.comp_out(latent)
        # x = tok_emb + xx

        prefix = xx
        self.print_once(torch.stack([prefix.max(), prefix.min()],0))

        ### resampled representation q( z|d )
        ### STE estimator

        _disabled = self._disabled
        # _disabled = 1;  
        if _disabled==1:
            self.print_once('[DEBUG]Disabling the latent!!!!!!!!------------')
            ### quality checking the noise
            prefix = prefix.flip((0,))
        
        ne = self.config.n_embd
        v = (self.selector(xout[:,0]).reshape(ns*b,ne,-1)/ne**0.5)
        v = torch.einsum('be,bek->bk',xout[:,0], v)
        vp = v.softmax(-1)
        # _,idxk = v.max(-1)


        dist = torch.distributions.categorical.Categorical(probs=vp)
        _disabled = self._disabled
        _disabled = 0
        # _disabled = 4
        
        if _disabled==4:
            self.print_once('[disabled mixture latent]--------------------------------------')
            dist = torch.distributions.categorical.Categorical(logits=vp*0)
            idxk = dist.sample()
        elif not self.training:
            self.print_once('[evaluating with greedy decoding]------------------------------')
            _, idxk = vp.max(dim=-1)
        else:
            idxk = dist.sample()

        nk = v.shape[-1]
        veck = (torch.eye(nk, device=x.device)[idxk,:]- vp ).detach()+vp

        # self.print_once((veck[:2]*100).long())
        self.print_once((vp[:2]*100).long())
        self.print_once((vp.mean(0)*100).long())

        ### decoder loss
        logits, lpy = self.decode_with_prefix(self.transformer.h_dec, prefix, idx, targets,veck, sum=1)
        if _disabled==2:
            self.print_once('[debug]disable prior')
        else:
            lpy = lpy - math.log(self.nsep)*nm*nm_a - self.extra_loss
        lpy1,lpy2 = torch.split(lpy, ns*b//2, dim=0)
        self.print_once(torch.stack([lpy1,lpy2],0).mean(1).squeeze(-1))

        ### adding                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
        if not self.training:
            loss = (lpy1+lpy2)/2
            loss = -loss.mean() / t
        else:            
            ### decoder loss + encoder loss
            loss = (lpy1+lpy2)/2
            loss = -(loss.mean() + lpe.mean())/ t

        if self.reset and not self.training:
            self.reset = False

        return logits, loss      






