            h_dec = nn.ModuleList([Block547(config, is_attn=1) for _ in range(config.n_layer//2)]),
            h_enc = nn.ModuleList([Block547(config, is_attn=1) for _ in range(config.n_layer//2)] ),
            # h_prior = nn.ModuleList([Block235(config) for _ in range(config.n_layer//2)] ),
            # hlast = Block231(config),
            ln_f = LayerNorm(config.n_embd, bias=config.bias),
