class LGT599A(LGT527A):
    '''
    prior: tfm
    latent: clipped xz
    '''
    logsigma = math.log(0.5)

    is_detach_ae=True ### whether to detach encoding gradient 

    def __init__(self, config):
        super(GPT,self).__init__()

        assert config.vocab_size is not None
        assert config.block_size is not None
        config = copy.copy(config)
        self.config = config

        vmax = config.vocab_size+500+10
        # nm = 10
        self.vmax = vmax
        self.nm = config.nm = nm = 1
        self.ns = 3
        self.nm_a = config.nm_a  = nm_a = config.n_embd
        # self.nm_a = config.nm_a = nm_a = 64 ### R2
        self.nk = nk = 100
        self.nlow = nlow = 16
        self.extra_loss = math.log(nk)
        #  + (nsub)*math.log(10.)

        # self.extra_loss = (math.lgamma(256+1) - math.lgamma(240+1) - math.lgamma(16+1)) + (nsub)*math.log(10.)

        self.low  = config.low  = low  = -3.0
        self.high = config.high = high =  3.0
        # self.nsep = config.nsep = 5
        self.nsep = config.nsep = nsep = 10
        self.sep = (self.high -self.low)/self.nsep
        # self.sep = 0.05
        self.lseg = 32

        self.transformer = nn.ModuleDict(dict(
            wte = nn.Embedding(vmax, config.n_embd),
            wpe = nn.Embedding(config.block_size+nm*2, config.n_embd),
            wpe2 = nn.Embedding(config.block_size+nm*2, config.n_embd),

            # comp_in = nn.Linear(config.n_embd*nm, nm_a,bias=False),
            # comp_out = nn.Linear(nm_a, config.n_embd*nm, bias=False),

            drop = nn.Dropout(config.dropout),
            
            # h0 = nn.ModuleList([Block140(config) for _ in range(1)]),
            h_dec = nn.ModuleList([Block235(config, is_attn=1) for _ in range(config.n_layer//2)]),
            h_enc = nn.ModuleList([Block235(config, is_attn=1) for _ in range(config.n_layer//2)] ),
            # h_prior = nn.ModuleList([Block235(config) for _ in range(config.n_layer//2)] ),
            # hlast = Block231(config),
            ln_f = LayerNorm(config.n_embd, bias=config.bias),
            ln_f2 = LayerNorm(config.n_embd, bias=config.bias),
            ln_f3 = LayerNorm(config.n_embd, bias=config.bias),
        ))
        # self.transformer.comp_in.weight = nn.Parameter(torch.eye(config.n_embd)[:nm_a],requires_grad=False)
        # self.transformer.comp_out.weight = nn.Parameter(torch.eye(config.n_embd)[:,:nm_a],requires_grad=False)
        # self.encoder = nn.Linear(config.block_size*config.n_embd, nm_a, bias=False)
        self.lm_head = nn.Linear(config.n_embd, vmax, bias=False)
        self.kin = nn.Linear(config.n_embd, nk*nlow,bias=False)
        self.kavg = nn.Linear(nk, config.n_embd, bias=False)
        self.kout = nn.Linear(nk*nlow,config.n_embd, bias=False)
        # self.lm_norm = nn.Linear(1, config.vocab_size, bias=True)
        # self.lm_null = nn.Linear(1, config.vocab_size, bias=False)
        # self.norm_m = nn.Parameter(torch.tensor(7.5))
        ### precision of the gaussian distrib
        self.norm_w = nn.Parameter(torch.tensor(0.))
        # self.norm_b = nn.Parameter(torch.tensor(0.))

        # with weight tying when using torch.compile() some warnings get generated:
        # "UserWarning: functional_call was passed multiple values for tied weights.
        # This behavior is deprecated and will be an error in future versions"
        # not 100% sure what this is, so far seems to be harmless. TODO investigate
        self.transformer.wte.weight = self.lm_head.weight # https://paperswithcode.com/method/weight-tying





        # init all weights
        self.apply(self._init_weights)
        # apply special scaled init to the residual projections, per GPT-2 paper
        for pn, p in self.named_parameters():
            if pn.endswith('c_proj.weight'):
                torch.nn.init.normal_(p, mean=0.0, std=0.02/math.sqrt(2 * config.n_layer))

        # report number of parameters
        print("number of parameters: %.2fM" % (self.get_num_params()/1e6,))
        self.reset = True

        # self.prior_logsigma = nn.Parameter(torch.tensor(math.log(0.1),device=x.device))
        # self.post_logsigma = nn.Parameter(torch.tensor(math.log(0.1),device=x.device))

        # self.prior_logsigma = nn.Parameter(torch.tensor(math.log(0.1)))
        # self.post_logsigma = nn.Parameter(torch.tensor(math.log(0.1)))
        self.logsigma = math.log(0.5)

        self._disabled=0
        # self._disabled=1
        self._disabled=2

    def decode_with_prefix(self, blocks, prefix, idx, targets, sel=None, sum=1):
        return self._decode_with_prefix(blocks, prefix[:,1:2], idx, targets, sel=sel, sum=sum)

    def _decode_with_prefix(self, blocks, prefix, idx, targets, sel=None, sum=1):

        device = idx.device
        b, t  = idx.size()[:2]

        nm = 0
        if prefix is not None:
            nm = prefix.size()[1]
        nm_a = self.nm_a
        #### decoding the sequence based on the prefix

        ### concating the ending segment to the left of decoder
        if len(idx.shape)==2:
            pos = torch.arange(0, t, dtype=torch.long, device=device) + 0 # shape (t)
            pos_emb = self.transformer.wpe(pos) # position embeddings of shape (t, n_embd)
            tok_emb = self.transformer.wte(idx) # token embeddings of shape (b, t, n_embd)


            ### dont add positional info to latent
            x = tok_emb + pos_emb
        else:
            x = idx

        if prefix is not None:
            self.print_once(prefix.shape)
            prefix = prefix.reshape(len(prefix),nm,-1)
            x = torch.cat([prefix, x],dim=1)

        for block in blocks:
            x = block(x,x)

        x = x[:,nm:]
        x = self.transformer.ln_f(x)
        if sel is not None:
            x = x[:,sel]
            targets = targets[:,sel]



        logits = self.lm_head(x)
        lpy = None
        if targets is not None:
            loss = F.cross_entropy(logits.view(-1, logits.size(-1)), targets.reshape(-1), ignore_index=-1,reduction='none')
            lpy = -loss.reshape((b,1,-1))
            if sum==1:
                lpy = lpy.sum(-1)        
        return logits,lpy





    def lat_code_to_prefix(self, xint):
        sep  = self.sep
        low  = self.low
        high = self.high

        latent = (xint + 0.5) * sep + low 
        # latent = ((xint + 0.5) * sep + low - latent).detach() + latent

        self.print_once([latent.shape,sep,low,high])
        # self.print_once(torch.stack([xint.max(),xint.min()],0))
        # self.print_once(torch.stack([latent.max(),latent.min()],0))
        # self.print_once(torch.stack([tok_emb.max(),tok_emb.min()],0))
        # prefix = self.transformer.comp_out(latent)
        xx = latent
        # xx = torch.einsum('mke,bme->bmk',self.transformer.comp_out.weight.reshape( self.nm,self.config.n_embd,self.nm_a), latent)

        return xx

    # def wrap_decode_with_prefix(self,prefix,idx,targets,sel=None,sum=1):
    #     logits, lpy = self.decode_with_prefix(self.transformer.h_dec, prefix[:,1:2], idx, targets,sel=sel, sum=sum)
        
    #     return logits,lpy



    def encode(self,idx,imax=-1):
        b,t = idx.size()[:2]
        nm = self.nm
        device= idx.device
        low =self.low
        high = self.high
        sep = self.sep
        ns = 1






        idxx = torch.cat([idx, torch.ones((ns*b,nm),device=device).long()*(self.vmax-1)],dim=1)

        pos  = torch.arange(0,t+nm, dtype=torch.long, device=device)  # shape (t)
        # targ_emb = self.transformer.wte(targets) # token embeddings of shape (b, t, n_embd)
        tok_emb = self.transformer.wte(idxx)     # token embeddings of shape (b, t, n_embd)
        pos_emb = self.transformer.wpe2(pos)      # position embeddings of shape (t, n_embd)
        x = tok_emb + pos_emb

        for block in self.transformer.h_enc:
            x = block(x,x)
        x = self.transformer.ln_f2(x)
        x = x[:,-nm:]
        ###
        
        xd = x.unsqueeze(-1) - self.kavg.weight[None,None]
        # xk = self.kin(x).reshape(ns*b,self.nm, self.nk, -1)
        msq2 = (xd).square().mean(2)
        idxb = torch.arange(ns*b,device=device)[:,None,]
        idxm = torch.arange(nm,device=device)[None,:]
        _, idxk = msq2.min(dim=-1)
        xdk = xd[idxb,idxm,:,idxk]
        # xdk = xd[idxb,0,:,idxk]

        xk = torch.einsum('bme,bmge->bmg',xdk, self.kin.weight.reshape(self.nk,-1, self.config.n_embd)[idxk])
        xo = torch.einsum('bmg,bmge->bme',xk, self.kout.weight.reshape(self.nk,-1, self.config.n_embd)[idxk])

        xk1 = torch.einsum('bme,bmge->bmg',xdk.detach(), self.kin.weight.reshape(self.nk,-1, self.config.n_embd)[idxk])
        xo1 = torch.einsum('bmg,bmge->bme',xk, self.kout.weight.reshape(self.nk,-1, self.config.n_embd)[idxk])

        ### autoencoding the local deviation
        # vmsq = (xo - (x.detach().unsqueeze(-1) - self.kavg.weight.T[idxk])).square().mean(-1)
        vmsq = (-x + xo1 + self.kavg.weight.T[idxk]).square().mean(-1)

        x = xo + self.kavg.weight.T[idxk]
        # x = xo[idxb,0,idxk,:] + self.kavg.weight.T[idxk]

        # print(idxk.shape,xk.shape,idxk.shape,x.shape)


        ### truncating the output to desired dimension
        # latent = self.transformer.comp_in(x.reshape(ns*b,1,-1))
        latent = x
        low  = self.low
        high = self.high
        sep  = self.sep
        lpe = -5. * (latent - latent.clip(low,high)).square().sum(-1).sum(-1,keepdims=True)
        lpe = lpe  - 0.1*vmsq.sum(-1,keepdims=True)

        xint = ((latent.clip(low, high-0.5*sep) - low )//sep)
        # latent = ((xint + torch.rand_like(xint)) * sep + low - latent).detach() + latent
        latent = ((xint + 0.5) * sep + low - latent).detach() + latent

        # self.print_once([latent.shape,sep,low,high])
        # # self.print_once(torch.stack([xint.max(),xint.min()],0))
        # self.print_once(torch.stack([latent.max(),latent.min()],0))
        # self.print_once(torch.stack([tok_emb.max(),tok_emb.min()],0))
        xx = latent 
        # xx = torch.einsum('mke,bme->bmk',self.transformer.comp_out.weight.reshape(nm,self.config.n_embd,self.nm_a), latent)


        latent = latent.clip(low,high)
        return xint, latent        



    def forward(self, idx, targets=None):
        '''
        the first token of index is masked to vmax-2
        '''

        if self.training:
            self.reset = True


        device = idx.device
        b, t = idx.size()
        assert t <= self.config.block_size, f"Cannot forward sequence of length {t}, block size is only {self.config.block_size}"
        low = self.low
        high = self.high
        nsep = self.nsep
        sep = self.sep

        ns = self.ns
        nm = self.nm
        nm_a = self.nm_a
        

        if self.training:
            self.reset = True


        lseg = self.lseg
        nseg = t//self.lseg
        assert nseg  == 2,(t,lseg,nseg)
        assert t%self.lseg==0, f"cannot split into segment ({t} // {self.lseg})"
        

        x = idx



        idx1,idx2 = torch.split(idx,t//2,1)
        targets1, targets2 = torch.split(targets,t//2,1) 
        idx3 = torch.cat([idx1,idx1],1)
        targets3 = torch.cat([targets1,targets1],1)

        idx = torch.cat([idx,idx3],0)
        targets = torch.cat([targets,targets3],0)
        b = b*2

        ### predict the last token only

        idx = idx.repeat((ns,1,1)).reshape((ns*b,t))
        targets = targets.repeat((ns,1,1)).reshape((ns*b,t))


        idx1,idx2 = torch.split(idx,t//2,1)
        targets1, targets2 = torch.split(targets,t//2,1) 





        
        idxcol = torch.ones((ns*b,nseg,nm),device=device).long()
        idxx= torch.cat([
            idx.reshape((ns*b,nseg,lseg)),
            idxcol*(self.vmax-1),
        ],2) 
        
        
        pos  = torch.arange(0,t+nm, dtype=torch.long, device=device)  # shape (t)
        # targ_emb = self.transformer.wte(targets) # token embeddings of shape (b, t, n_embd)
        tok_emb = self.transformer.wte(idxx)     # token embeddings of shape (b, t, n_embd)
        pos_emb = self.transformer.wpe2(pos)      # position embeddings of shape (t, n_embd)
        x = tok_emb + pos_emb

        for block in self.transformer.h_enc:
            x = block(x,x)
        x = self.transformer.ln_f2(x)
        x = x.reshape((ns*b,nseg,nm,-1))
        x = x[:,:,-nm:].reshape(ns*b,nseg*nm,-1)
        ###
        
        xd = x.unsqueeze(-1) - self.kavg.weight[None,None]
        # xk = self.kin(x).reshape(ns*b,self.nm, self.nk, -1)
        msq2 = (xd).square().mean(2)
        idxb = torch.arange(ns*b,device=device)[:,None,]
        idxm = torch.arange(nm*nseg,device=device)[None,:]
        _, idxk = msq2.min(dim=-1)
        xdk = xd[idxb,idxm,:,idxk]
        # xdk = xd[idxb,0,:,idxk]


        xk = torch.einsum('bme,bmge->bmg',xdk, self.kin.weight.reshape(self.nk,-1, self.config.n_embd)[idxk])
        xo = torch.einsum('bmg,bmge->bme',xk, self.kout.weight.reshape(self.nk,-1, self.config.n_embd)[idxk])
        xo1 = xo

        xk1 = torch.einsum('bme,bmge->bmg',xdk.detach(), self.kin.weight.reshape(self.nk,-1, self.config.n_embd)[idxk])
        xo1 = torch.einsum('bmg,bmge->bme',xk, self.kout.weight.reshape(self.nk,-1, self.config.n_embd)[idxk])

        ### autoencoding the local deviation
        # vmsq = (xo - (x.detach().unsqueeze(-1) - self.kavg.weight.T[idxk])).square().mean(-1)
        vmsq = (-x.detach() + xo1 + self.kavg.weight.T[idxk]).square().mean(-1)

        x = (xo + self.kavg.weight.T[idxk] - x ).detach()+x
        # x = xo[idxb,0,idxk,:] + self.kavg.weight.T[idxk]

        # print(idxk.shape,xk.shape,idxk.shape,x.shape)


        ### truncating the output to desired dimension
        # latent = self.transformer.comp_in(x.reshape(ns*b,1,-1))
        latent = x
        low  = self.low
        high = self.high
        sep  = self.sep
        lpe = -5. * (latent - latent.clip(low,high)).square().sum(-1).sum(-1,keepdims=True)
        lpe = lpe  - 0.1*vmsq.sum(-1,keepdims=True)

        xint = ((latent.clip(low, high-0.5*sep) - low )//sep)
        # latent = ((xint + torch.rand_like(xint)) * sep + low - latent).detach() + latent
        latent = ((xint + 0.5) * sep + low - latent).detach() + latent

        self.print_once([latent.shape,sep,low,high])
        # self.print_once(torch.stack([xint.max(),xint.min()],0))
        self.print_once(torch.stack([latent.max(),latent.min()],0))
        self.print_once(torch.stack([tok_emb.max(),tok_emb.min()],0))
        xx = latent 
        # xx = torch.einsum('mke,bme->bmk',self.transformer.comp_out.weight.reshape(nm,self.config.n_embd,self.nm_a), latent)


        # xx = self.transformer.comp_out(latent).reshape(ns*b,-1,self.config.n_embd)
        # x = tok_emb + xx

        prefix = xx
        self.print_once(torch.stack([prefix.max(), prefix.min()],0))

        ### resampled representation q( z|d )
        ### STE estimator

        _disabled = self._disabled
        # _disabled = 1;  
        if _disabled==1:
            self.print_once('[DEBUG]Disabling the latent!!!!!!!!------------')
            ### quality checking the noise
            prefix = prefix.flip((0,))
        
        logits, lpy = self._decode_with_prefix(self.transformer.h_dec, prefix, idx, targets, sel=None,sum=0)
        lpya = None
        ### decoder loss
        # logits, lpya = self._decode_with_prefix(self.transformer.h_dec, prefix[:,0:1], idx[:,:t//2], targets[:,:t//2], sel=None,sum=1)
        # logits, lpy = self._decode_with_prefix(self.transformer.h_dec, prefix[:,1:2], idx, targets, sel=slice(t//2,None),sum=1)
        if _disabled==2:
            self.print_once('[debug]disable prior')
        else:
            lpy = lpy - math.log(self.nsep)*nm*nm_a - self.extra_loss
        lpy1,lpy2 = torch.split(lpy, ns*b//2, dim=0)
        self.print_once(torch.stack([lpy1,lpy2],0).mean(1).squeeze(-1))

        ### adding                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
        if not self.training:
            loss = (lpy1+lpy2)/2
            loss = -loss.mean() / t
        else:            
            ### decoder loss + encoder loss
            loss = (lpy1+lpy2)/2 + lpya.squeeze(-1)
            loss = -(loss.mean() + lpe.mean())/ t

        if self.reset and not self.training:
            self.reset = False

        return logits, loss      

    def post_encode_before_pca(self,xz_int, xz ):
        return xz_int, xz
        # return xz_int, xz[:,1:2] 
        # return xz_int, xz[:,0:1] 



